#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    int current_floor = 0;
    for (int i = 1; i < argc; i++) {
        int target_floor = atoi(argv[i]);
        if (target_floor < 0) {
            printf("INVALID_FLOOR\n");
            continue;
        }
        if (target_floor > current_floor) {
            while (current_floor < target_floor) {
                current_floor++;
                printf("MOVE_UP %d->%d\n", current_floor - 1, current_floor);
            }
        } else if (target_floor < current_floor) {
            while (current_floor > target_floor) {
                current_floor--;
                printf("MOVE_DOWN %d->%d\n", current_floor + 1, current_floor);
            }
        }
        printf("ARRIVE %d\n", target_floor);
        printf("DOORS_OPEN\n");
        printf("DOORS_CLOSE\n");
    }
    printf("FINAL_FLOOR=%d\n", current_floor);
    return 0;
}
